  {
   "@type": "Question",
   "name": "What does gray dog poop mean?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "It can mean bile isn't mixing in well, or the pancreas isn't making enough digestive enzymes. If it looks greasy or keeps happening, talk to your vet."
   }
  },
  {
   "@type": "Question",
   "name": "My dog's poop is white and crumbly.",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "This is common on diets high in bone or calcium. Constipation often comes with it, so cut back on bones and check with your vet."
   }
  },
  {
   "@type": "Question",
   "name": "My dog has yellow diarrhea with mucus.",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "The gut may be irritated, or it could be a parasite such as giardia. If it keeps coming back, get a stool test."
   }
